            let expr = self.parse_expression()?;
            let dir = if self.next_if_keyword() == Some(Keyword::Asc) {
                ast::Direction::Ascending
            } else if self.next_if_keyword() == Some(Keyword::Desc) {
                ast::Direction::Descending
            } else {
                ast::Direction::Ascending
            };
            order_by.push((expr, dir));
            if !self.next_is(Token::Comma) {
                break;
            }
        }
        Ok(order_by)
    }

